package com.tapeverify.copilot.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="loan_batches") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class LoanBatch { @Id @Column(length=64) private String id; @Column(name="source_file_id",length=64) private String sourceFileId; @Column(name="source_type",nullable=false,length=32) @Builder.Default private String sourceType="PRIMARY"; @Column(name="source_filename",nullable=false) private String sourceFilename; @Column(name="uploaded_by",nullable=false) private String uploadedBy; @Column(name="uploaded_at",nullable=false) private LocalDateTime uploadedAt; @Column(name="total_rows",nullable=false) private int totalRows; @Column(name="valid_rows",nullable=false) private int validRows; @Column(name="exception_rows",nullable=false) private int exceptionRows; @Column(name="failed_rows",nullable=false) private int failedRows; @Column(nullable=false,length=32) private String status; }
